import{_ as t,c as a,o as i,aj as r}from"./chunks/framework.CDhdelVI.js";const m=JSON.parse('{"title":"Preferments","description":"Learn how to use poolish and biga in the KitchenRatio calculator to improve flavor, structure, and fermentation control.","frontmatter":{"title":"Preferments","description":"Learn how to use poolish and biga in the KitchenRatio calculator to improve flavor, structure, and fermentation control.","head":[["meta",{"name":"description","content":"Learn how to use poolish and biga in the KitchenRatio calculator to improve flavor, structure, and fermentation control."}],["meta",{"property":"og:title","content":"Preferments"}],["meta",{"property":"og:description","content":"Learn how to use poolish and biga in the KitchenRatio calculator to improve flavor, structure, and fermentation control."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/guides/preferments.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Preferments"}],["meta",{"name":"twitter:description","content":"Learn how to use poolish and biga in the KitchenRatio calculator to improve flavor, structure, and fermentation control."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/guides/preferments.html"}]]},"headers":[],"relativePath":"guides/preferments.md","filePath":"guides/preferments.md"}'),o={name:"guides/preferments.md"};function l(n,e,s,h,d,u){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="preferments" tabindex="-1">Preferments <a class="header-anchor" href="#preferments" aria-label="Permalink to “Preferments”">​</a></h1><p>Preferments are dough &quot;pre-games&quot;: part of your flour and water mixed ahead of time so the final dough starts with momentum. Done well, they buy you better flavor, better fermentation behavior, and nicer handling.</p><p>In the KitchenRatio calculator, preferments live in <strong>Advanced → Preferments</strong>.</p><h2 id="types-in-the-calculator" tabindex="-1">Types in the Calculator <a class="header-anchor" href="#types-in-the-calculator" aria-label="Permalink to “Types in the Calculator”">​</a></h2><ul><li><strong>Poolish</strong><br> Wet and loose, usually near 100% hydration, often fermented 12 to 16 hours.</li><li><strong>Biga</strong><br> Stiffer and chunkier, lower hydration, usually chosen for strength and deeper flavor.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>The calculator allows only one preferment type at a time: poolish or biga.</p></div><h2 id="other-preferment-style-not-in-calculator-yet" tabindex="-1">Other Preferment Style (Not in Calculator Yet) <a class="header-anchor" href="#other-preferment-style-not-in-calculator-yet" aria-label="Permalink to “Other Preferment Style (Not in Calculator Yet)”">​</a></h2><h3 id="pate-fermentee-pate-fermentee" tabindex="-1">Pate fermentee (Pâte fermentée) <a class="header-anchor" href="#pate-fermentee-pate-fermentee" aria-label="Permalink to “Pate fermentee (Pâte fermentée)”">​</a></h3><p>Pate fermentee (&quot;old dough&quot;) is exactly what it sounds like: a piece of fully mixed dough saved from a previous batch and used to seed the next one. Think of it as a flavor relay baton from one bake to the next.</p><p>Where it came from:</p><ul><li>Traditional French and broader European baking practice, especially in systems where dough was mixed daily and a portion was intentionally held back.</li></ul><p>How it behaves:</p><ul><li>Already contains flour, water, salt, and yeast.</li><li>Brings mature flavor and extra fermentation confidence to new dough.</li><li>Usually adds strength and structure more than extreme openness.</li></ul><p>Typical use in practice:</p><ul><li>Commonly used around <strong>10 to 30%</strong> of total flour contribution in the next dough.</li><li>Particularly useful for lean breads where you want depth without changing the whole process.</li><li>Because it already has salt, formulas usually account for that in the final mix.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Pâte fermentée is usually a &quot;same dough in, same dough out&quot; workflow. You hold back a piece of dough from today, then add it to tomorrow&#39;s batch, so there is far less separate measuring than with poolish or biga.</p></div><p>Quick walkthrough:</p><ol><li>Mix your normal dough formula as usual.</li><li>Before bulk fermentation is complete (or right after mixing, depending on your routine), remove a small piece of dough.</li><li>Store that piece covered in the fridge until the next mix.</li><li>In the next batch, add that old dough piece during initial mixing.</li><li>Make a new hold-back piece from the new batch to continue the cycle.</li><li>If the dough piece gets too old, acidic, or weak, reset with a fresh cycle.</li></ol><h2 id="when-to-use-which" tabindex="-1">When to Use Which <a class="header-anchor" href="#when-to-use-which" aria-label="Permalink to “When to Use Which”">​</a></h2><ul><li><strong>Use poolish</strong> when you want: <ul><li>a dough that stretches easier</li><li>a more open crumb</li><li>mellow, rounded fermentation flavor</li></ul></li><li><strong>Use biga</strong> when you want: <ul><li>stronger structure and shape tolerance</li><li>a tighter, drier feel during mixing</li><li>deeper flavor without turning the dough into soup</li></ul></li><li><strong>Use pâte fermentée</strong> when you want: <ul><li>a low-fuss, repeatable preferment workflow</li><li>more flavor and strength without extra side builds</li><li>continuity from one batch to the next</li></ul></li></ul><h2 id="deeper-breakdown" tabindex="-1">Deeper Breakdown <a class="header-anchor" href="#deeper-breakdown" aria-label="Permalink to “Deeper Breakdown”">​</a></h2><h3 id="poolish" tabindex="-1">Poolish <a class="header-anchor" href="#poolish" aria-label="Permalink to “Poolish”">​</a></h3><ul><li>Hydration is usually high (often near 100%), so it matures quickly.</li><li>It usually increases extensibility, which helps with stretch and open crumb.</li><li>Great fit for lean doughs and many pizza styles.</li><li>If it overripens, final dough can get sticky, slack, and annoying.</li></ul><h3 id="biga" tabindex="-1">Biga <a class="header-anchor" href="#biga" aria-label="Permalink to “Biga”">​</a></h3><ul><li>Hydration is lower, so fermentation progresses differently and structure stays firmer.</li><li>It usually improves strength and shaping tolerance.</li><li>Useful when you want chew and a more assertive dough network.</li><li>If too dry or underdeveloped, final dough can feel tight and uneven.</li></ul><h3 id="pate-fermentee-pate-fermentee-1" tabindex="-1">Pate fermentee (Pâte fermentée) <a class="header-anchor" href="#pate-fermentee-pate-fermentee-1" aria-label="Permalink to “Pate fermentee (Pâte fermentée)”">​</a></h3><ul><li>It is old dough: already salted, already fermented, already familiar.</li><li>It contributes mature flavor and often better dough confidence in the next batch.</li><li>It is less about changing hydration style and more about process continuity.</li><li>Because salt is already present in the held dough, final mix balance still matters.</li></ul><h2 id="where-they-came-from" tabindex="-1">Where They Came From <a class="header-anchor" href="#where-they-came-from" aria-label="Permalink to “Where They Came From”">​</a></h2><ul><li><strong>Poolish</strong> is commonly tied to 19th-century Polish bakers working in France, and became a staple in French-style bread workflows.</li><li><strong>Biga</strong> is the Italian preferment tradition, heavily used in breads and pizza where strength and flavor layering matter.</li></ul><h2 id="typical-use-in-practice" tabindex="-1">Typical Use in Practice <a class="header-anchor" href="#typical-use-in-practice" aria-label="Permalink to “Typical Use in Practice”">​</a></h2><ul><li><strong>Poolish</strong> shows up in baguette-style and lean doughs when extensibility and openness are the goal.</li><li><strong>Biga</strong> shows up when bakers want more structure and chew, especially in many Italian-style breads and pizzas.</li><li><strong>Pâte fermentée</strong> shows up in bakeries and home routines where the same dough is made repeatedly and a piece is carried forward.</li><li>All three are used to build flavor without relying only on long final-proof times.</li></ul><h2 id="how-allocation-works" tabindex="-1">How Allocation Works <a class="header-anchor" href="#how-allocation-works" aria-label="Permalink to “How Allocation Works”">​</a></h2><p>The calculator does not add extra flour and water on top of your formula. Instead, it allocates part of your existing flour and water into the preferment.</p><ul><li><strong>Preferment flour grams</strong> = total flour × flour allocation %</li><li><strong>Preferment water grams</strong> = preferment flour × hydration %</li></ul><p>You also get live totals for:</p><ul><li>allocated flour and water</li><li>remaining main dough flour and water</li></ul><h2 id="poolish-settings" tabindex="-1">Poolish Settings <a class="header-anchor" href="#poolish-settings" aria-label="Permalink to “Poolish Settings”">​</a></h2><ul><li>Flour allocation: <strong>0 to 60%</strong> (default <strong>20%</strong>)</li><li>Hydration: <strong>50 to 130%</strong> (default <strong>100%</strong>)</li></ul><h2 id="biga-settings" tabindex="-1">Biga Settings <a class="header-anchor" href="#biga-settings" aria-label="Permalink to “Biga Settings”">​</a></h2><ul><li>Flour allocation: <strong>0 to 60%</strong> (default <strong>20%</strong>)</li><li>Hydration: <strong>45 to 80%</strong> (default <strong>60%</strong>)</li></ul><h2 id="how-to-make-poolish" tabindex="-1">How to Make Poolish <a class="header-anchor" href="#how-to-make-poolish" aria-label="Permalink to “How to Make Poolish”">​</a></h2><ol><li>Weigh flour and water at equal weight (100% hydration).</li><li>Add a small amount of yeast and mix until smooth.</li><li>Cover loosely and ferment at room temperature.</li><li>Let it mature until domed, bubbly, and just beginning to flatten.</li><li>Use it in final dough while it is still active.</li></ol><p>Typical timing:</p><ul><li>About <strong>12 to 16 hours</strong> around normal room temperature.</li><li>Warmer rooms shorten this; cooler rooms lengthen it.</li></ul><p>Signs it is ready:</p><ul><li>Surface is bubbly and aerated.</li><li>Smell is sweet and fermented, not harsh.</li><li>Top is near peak or just starting to recede.</li></ul><h2 id="how-to-make-biga" tabindex="-1">How to Make Biga <a class="header-anchor" href="#how-to-make-biga" aria-label="Permalink to “How to Make Biga”">​</a></h2><ol><li>Weigh flour and lower water amount (stiff hydration, often near 50 to 60%).</li><li>Add a small amount of yeast and mix just until combined.</li><li>Keep it shaggy or chunky; do not fully smooth it out.</li><li>Cover and ferment until expanded and aromatic.</li><li>Tear into pieces and incorporate into final dough.</li></ol><p>Typical timing:</p><ul><li>Usually <strong>12 to 16 hours</strong> depending on yeast amount and room temperature.</li></ul><p>Signs it is ready:</p><ul><li>Noticeable volume increase.</li><li>Interior shows airy structure when torn open.</li><li>Aroma is mature and wheaty, without sharp sourness.</li></ul><h2 id="practical-workflow" tabindex="-1">Practical Workflow <a class="header-anchor" href="#practical-workflow" aria-label="Permalink to “Practical Workflow”">​</a></h2><ol><li>Build your base formula in the calculator.</li><li>Open <strong>Advanced → Preferments</strong>.</li><li>Enable poolish or biga.</li><li>Set flour allocation and hydration.</li><li>Use the shown preferment flour/water grams when mixing your preferment.</li><li>Mix the final dough with the remaining flour and water amounts shown in Advanced.</li></ol><p>For pâte fermentée (not in calculator yet), run it manually:</p><ol><li>Hold back a piece of today’s finished dough.</li><li>Chill it covered.</li><li>Add it to tomorrow’s mix.</li><li>Repeat with a fresh hold-back piece from each batch.</li></ol><h2 id="practical-tips" tabindex="-1">Practical Tips <a class="header-anchor" href="#practical-tips" aria-label="Permalink to “Practical Tips”">​</a></h2><ul><li>Start around 15 to 25% flour allocation if you are new to preferments.</li><li>If you are unsure, start with poolish for easier handling.</li><li>Reach for biga when your dough keeps feeling too loose.</li><li>Use pâte fermentée when you are baking the same dough repeatedly and want consistency with less side prep.</li><li>Keep an eye on total water behavior with <a href="/guides/hydration.html">Hydration</a>.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><ul><li><strong>Dough feels too slack after adding preferment</strong><ul><li>Lower preferment allocation by 5 to 10%.</li><li>Shorten preferment ripening time.</li></ul></li><li><strong>Dough feels too tight or dense</strong><ul><li>Increase preferment hydration slightly.</li><li>Use a smaller preferment and longer final fermentation.</li></ul></li><li><strong>Weak rise or dull flavor</strong><ul><li>Check preferment maturity before mixing the final dough.</li><li>Verify yeast amount and room temperature.</li></ul></li></ul><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><ul><li><a href="/guides/scalds.html">Scalds</a></li><li><a href="/guides/kitchenratio-calculator.html">KitchenRatio Calculator</a></li><li><a href="/guides/hydration.html">Hydration</a></li></ul><h2 id="get-the-gear" tabindex="-1">Get the Gear <a class="header-anchor" href="#get-the-gear" aria-label="Permalink to “Get the Gear”">​</a></h2><ul><li><a href="/guides/baking-gear-and-ingredients.html">Baking Gear &amp; Ingredients</a></li></ul>',64)])])}const f=t(o,[["render",l]]);export{m as __pageData,f as default};
